class LRU<K,V> extends LinkedHashMap<K,V> {
  private final int cap;
  LRU(int cap) { super(16, 0.75f, true); this.cap = cap; }
  @Override protected boolean removeEldestEntry(Map.Entry<K,V> e) { return size() > cap; }
}

class TokenBucket {
  private final double cap, rate; private double tokens; private long last = System.nanoTime();
  TokenBucket(double cap, double rate) { this.cap = cap; this.rate = rate; this.tokens = cap; }
  synchronized boolean tryAcquire() {
    long now = System.nanoTime();
    tokens = Math.min(cap, tokens + (now - last) / 1e9 * rate); last = now;
    if (tokens >= 1) { tokens -= 1; return true; } return false;
  }
}

interface Vehicle { int spotsNeeded(); }
class Car implements Vehicle {
  @Override public int spotsNeeded() { return 1; }
}
